from __future__ import annotations

import os
from pathlib import Path
from typing import Any

from mcp.server.fastmcp import FastMCP
from starlette.requests import Request
from starlette.responses import JSONResponse


PROJECT_ROOT = Path(__file__).resolve().parent
CONVENTIONAL_DOCUMENT_DIRECTORY = PROJECT_ROOT / "docs"
EXISTING_DOCUMENT_DIRECTORY = PROJECT_ROOT / "ribanc"
DEFAULT_DOCUMENT_DIRECTORY = (
    CONVENTIONAL_DOCUMENT_DIRECTORY
    if CONVENTIONAL_DOCUMENT_DIRECTORY.is_dir()
    else EXISTING_DOCUMENT_DIRECTORY
)

DOCUMENT_DIRECTORY = Path(
    os.environ.get("DOCS_DIR", str(DEFAULT_DOCUMENT_DIRECTORY))
).expanduser()
if not DOCUMENT_DIRECTORY.is_absolute():
    DOCUMENT_DIRECTORY = PROJECT_ROOT / DOCUMENT_DIRECTORY
DOCUMENT_DIRECTORY = DOCUMENT_DIRECTORY.resolve()

HOST = os.environ.get("HOST", "0.0.0.0")
PORT_VALUE = os.environ.get("PORT", "8000")

try:
    PORT = int(PORT_VALUE)
except ValueError as exc:
    raise ValueError("PORT must be an integer") from exc

if not 1 <= PORT <= 65535:
    raise ValueError("PORT must be between 1 and 65535")

mcp = FastMCP(
    "Markdown Documentation",
    host=HOST,
    port=PORT,
    streamable_http_path="/mcp",
    stateless_http=True,
    json_response=True,
)


def _ensure_document_directory() -> None:
    if not DOCUMENT_DIRECTORY.exists():
        raise FileNotFoundError(
            f"Markdown directory does not exist: {DOCUMENT_DIRECTORY}"
        )
    if not DOCUMENT_DIRECTORY.is_dir():
        raise NotADirectoryError(
            f"Markdown path is not a directory: {DOCUMENT_DIRECTORY}"
        )


def _relative_filename(path: Path) -> str:
    return path.relative_to(DOCUMENT_DIRECTORY).as_posix()


def _markdown_files() -> list[Path]:
    _ensure_document_directory()
    files: set[Path] = set()

    try:
        candidates = DOCUMENT_DIRECTORY.rglob("*")
        for path in candidates:
            try:
                if path.suffix.lower() != ".md" or not path.is_file():
                    continue
                resolved_path = path.resolve(strict=True)
                resolved_path.relative_to(DOCUMENT_DIRECTORY)
            except (FileNotFoundError, OSError, RuntimeError, ValueError):
                continue
            files.add(resolved_path)
    except OSError as exc:
        raise RuntimeError(
            f"Unable to scan Markdown directory: {DOCUMENT_DIRECTORY}"
        ) from exc

    return sorted(files, key=_relative_filename)


def _resolve_filename(filename: str) -> Path:
    _ensure_document_directory()

    if not isinstance(filename, str) or not filename.strip():
        raise ValueError("filename must be a non-empty string")
    if "\x00" in filename:
        raise ValueError("filename contains an invalid null character")

    requested = Path(filename)
    if requested.is_absolute():
        raise ValueError("filename must be relative to the Markdown directory")

    try:
        candidate = (DOCUMENT_DIRECTORY / requested).resolve(strict=True)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"Markdown file not found: {filename}") from exc
    except (OSError, RuntimeError) as exc:
        raise ValueError(f"Unable to resolve Markdown filename: {filename}") from exc

    try:
        candidate.relative_to(DOCUMENT_DIRECTORY)
    except ValueError as exc:
        raise ValueError(
            "filename must remain inside the Markdown directory"
        ) from exc

    if candidate.suffix.lower() != ".md":
        raise ValueError("filename must identify a .md file")
    if not candidate.is_file():
        raise FileNotFoundError(f"Markdown file not found: {filename}")

    return candidate


def _read_utf8_document(path: Path) -> str:
    filename = _relative_filename(path)

    try:
        with path.open("r", encoding="utf-8", newline="") as document:
            return document.read()
    except UnicodeDecodeError as exc:
        raise ValueError(
            f"Markdown file is not valid UTF-8: {filename}"
        ) from exc
    except OSError as exc:
        raise RuntimeError(
            f"Unable to read Markdown file: {filename}"
        ) from exc


@mcp.tool()
def list_markdown_files() -> dict[str, Any]:
    """List every available Markdown filename in the configured directory."""
    files = _markdown_files()
    return {
        "directory": str(DOCUMENT_DIRECTORY),
        "files": [_relative_filename(path) for path in files],
        "total_files": len(files),
    }


@mcp.tool()
def read_markdown_file(filename: str) -> dict[str, Any]:
    """Return the complete UTF-8 contents of one Markdown file exactly as stored."""
    path = _resolve_filename(filename)
    content = _read_utf8_document(path)

    return {
        "filename": _relative_filename(path),
        "content": content,
    }


@mcp.tool()
def search_markdown(
    query: str,
    case_sensitive: bool = False,
    context_lines: int = 1,
) -> dict[str, Any]:
    """Search every Markdown file for all lines containing a literal query."""
    if not isinstance(query, str) or not query:
        raise ValueError("query must be a non-empty string")
    if "\x00" in query:
        raise ValueError("query contains an invalid null character")
    if not isinstance(case_sensitive, bool):
        raise ValueError("case_sensitive must be a boolean")
    if not isinstance(context_lines, int) or isinstance(context_lines, bool):
        raise ValueError("context_lines must be an integer")
    if context_lines < 0:
        raise ValueError(
            "context_lines must be greater than or equal to zero"
        )

    comparison_query = query if case_sensitive else query.casefold()
    results: dict[str, dict[str, Any]] = {}
    total_matches = 0
    total_occurrences = 0

    for path in _markdown_files():
        filename = _relative_filename(path)
        content = _read_utf8_document(path)
        lines = content.splitlines()
        matches: list[dict[str, Any]] = []

        for index, line in enumerate(lines):
            comparison_line = line if case_sensitive else line.casefold()
            occurrence_count = comparison_line.count(comparison_query)

            if occurrence_count == 0:
                continue

            first_context_line = max(0, index - context_lines)
            last_context_line = min(
                len(lines),
                index + context_lines + 1,
            )
            context = [
                {
                    "line_number": context_index + 1,
                    "line": lines[context_index],
                }
                for context_index in range(
                    first_context_line,
                    last_context_line,
                )
            ]

            matches.append(
                {
                    "line_number": index + 1,
                    "match_line": line,
                    "occurrence_count": occurrence_count,
                    "context": context,
                }
            )
            total_occurrences += occurrence_count

        if matches:
            results[filename] = {
                "match_count": len(matches),
                "occurrence_count": sum(
                    match["occurrence_count"] for match in matches
                ),
                "matches": matches,
            }
            total_matches += len(matches)

    return {
        "query": query,
        "case_sensitive": case_sensitive,
        "context_lines": context_lines,
        "total_files_matched": len(results),
        "total_matches": total_matches,
        "total_occurrences": total_occurrences,
        "results": results,
    }


@mcp.custom_route(
    "/",
    methods=["GET"],
    name="health",
    include_in_schema=False,
)
async def health_check(_: Request) -> JSONResponse:
    """Return the service readiness status."""
    try:
        _ensure_document_directory()
    except (FileNotFoundError, NotADirectoryError) as exc:
        return JSONResponse(
            {
                "status": "error",
                "mcp_endpoint": "/mcp",
                "detail": str(exc),
            },
            status_code=503,
        )

    return JSONResponse(
        {
            "status": "ok",
            "mcp_endpoint": "/mcp",
        }
    )


if __name__ == "__main__":
    mcp.run(transport="streamable-http")


